layers.vertex:
attribute vec3 aO; attribute float aYaw, aM; attribute vec4 aS; uniform float uTime; varying vec2 vF; varying float vAge, vFrom, vTo, vM;
    void main(){
      if (aS.w < .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float age = uTime - aS.z, S = age < .24 ? 1.45 : .98;
      vAge = age; vFrom = aS.x; vTo = aS.y; vM = aM;
      if (aM > .5){                                     // buckle emblem: billboard just in front of the waist
        vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.0, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3;
        float B = .16*(age < .24 ? 1.25 : 1.); mv.xy += vec2(position.x, -position.z)*B; vF = vec2(position.x, -position.z)*.24 + vec2(0., -.76);
        gl_Position = projectionMatrix*mv; return;
      }
      vec2 l = position.xz*S;                           // marker units, -z = forward
      float c = cos(aYaw), s = sin(aYaw);
      vec2 w = vec2(c*l.x + s*l.y, -s*l.x + c*l.y)*.55;  // belt: 0.55 m per unit → crescents at ~0.36 m around the waist
      vF = vec2(l.x, -l.y);
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(w.x, 1.0, w.y), 1.);
    }

layers.fragment:
uniform float uTime; uniform vec3 uCW, uCT; varying vec2 vF; varying float vAge, vFrom, vTo, vM; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    // soft stroke: bright thin core + wide feathered halo (no hard edges, no flat facets)
    float stroke(float d, float w){ return exp(-(d*d)/(w*w)) + .28*exp(-(d*d)/(w*w*22.)); }
    float lineCore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec2 p = vF; float r = length(p), ang = atan(p.x, p.y), a = abs(ang);
      float k = clamp(vAge/.14, 0., 1.), m = mix(vFrom, vTo, k*k*(3.-2.*k));
      vec3 col = mix(uCW, uCT, m);
      // calligraphic crescents: taper to hair-fine tips, energy drifting slowly along the arc
      float t = clamp((a - .42)/2.25, 0., 1.), taper = pow(sin(3.14159*t), .7);
      float flow = .78 + .22*sin(a*9. - uTime*2.2 + sign(ang)*1.3);
      float arcA = stroke(r - .66, .006 + .016*taper) * step(.42, a) * step(a, 2.67) * taper * flow;
      float tb = clamp((a - .75)/1.6, 0., 1.), taperB = pow(sin(3.14159*tb), 1.2);
      float arcB = stroke(r - .57, .004 + .006*taperB) * step(.75, a) * step(a, 2.35) * taperB * .55;
      float core = lineCore(r - .66, .004 + .006*taper) * step(.42, a) * step(a, 2.67) * taper;
      // four glints where the icon has crystal shards: soft points that breathe
      float gl = 0.;
      for (int i=0;i<4;i++){
        float g = (i < 2 ? 1.15 : 2.05) * (mod(float(i),2.) < .5 ? 1. : -1.);
        vec2 c = .8*vec2(sin(g), cos(g)); float d2 = dot(p-c, p-c);
        gl += (exp(-d2/.00012) + .25*exp(-d2/.0025)) * (.7 + .3*sin(uTime*1.7 + float(i)*1.9));
      }
      // emblem in the back opening, drawn as fine line-art with a faint fill
      vec2 e = p - vec2(0., -.76);
      float bd = abs(e.x)/.05 + abs(e.y)/.19 - 1.;
      float blade = stroke(bd*.05, .006) + .12*step(bd, 0.);
      float top = .1, tip = -.13, hw = .1;
      float wy = e.y > 0. ? hw : hw*clamp((e.y - tip)/(0. - tip), 0., 1.);
      float sd = max(abs(e.x) - wy, max(e.y - top, tip - e.y));
      float shield = stroke(sd, .006) + .12*step(sd, 0.) + .5*lineCore(sd + .028, .004)*step(sd, 0.);
      float emblem = mix(blade, shield, m);
      if (vM > .5){                                               // buckle: only the emblem, faded before the quad edge
        float be = emblem*smoothstep(.24, .18, length(p - vec2(0., -.76)))*(vAge < .26 ? 1. + 1.1*exp(-max(vAge - .033, 0.)*16.) : 1.);
        vec3 bo = col*be*.9 + mix(col, vec3(1., .93, .9), .55)*be*.25;
        if (max(bo.r, max(bo.g, bo.b)) < .002) discard; gl_FragColor = vec4(bo*1.1, 1.); return;
      }
      float body = arcA + arcB + gl*.9;                           // belt: crescents + glints (the emblem is the buckle)
      // switch: 2-frame bloom peak, then a feathered ring with a thin leading edge
      float peak = vAge < .033 ? 2.2 : 1. + 1.1*exp(-(vAge-.033)*16.);
      float rr = mix(.4, 1.35, eox(clamp(vAge/.2, 0., 1.))), fade = 1. - clamp(vAge/.24, 0., 1.);
      float ring = (lineCore(r - rr, .012)*1.3 + exp(-pow((r-rr)/.09, 2.))*.35) * fade*fade * step(0., vAge);
      float disk = exp(-r*r*6.) * (vAge < .033 ? 1.2 : 0.);
      float lum = body*(vAge < .26 ? peak : 1.) + ring + disk;
      vec3 hot = mix(col, vec3(1., .93, .9), .55);             // near-white core, stance-tinted halo
      vec3 outc = col*lum + hot*(core*.9 + ring*.25)*(vAge < .26 ? peak : 1.);
      float S = vAge < .24 ? 1.45 : .98;
      outc *= smoothstep(S, S*.78, r);                            // everything fades to zero before the quad's edge — no visible square
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc*1.1, 1.);
    }

layers.vertex:
attribute vec3 aO, aV; attribute vec2 aT; attribute float aC; uniform float uTime; varying vec2 vUv; varying float vF; varying float vC;
    void main(){
      float age = uTime - aT.x; if (age < 0. || age > aT.y){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = 3., e = exp(-k*age); vec3 p = aO + aV*(1.-e)/k; p.y -= .3*9.8*(age*age*.5);
      float f = 1. - age/aT.y, sz = .09*(.4 + .6*f), rot = aC*3. + age*9.;
      vec4 mv = viewMatrix*vec4(p,1.); vec2 q = position.xy; q = vec2(cos(rot)*q.x - sin(rot)*q.y, sin(rot)*q.x + cos(rot)*q.y);
      mv.xy += q*vec2(sz*.9, sz*1.8); gl_Position = projectionMatrix*mv; vUv = position.xy; vF = f; vC = step(.5, fract(aC));
    }

layers.fragment:
uniform vec3 uCW, uCT; varying vec2 vUv; varying float vF, vC;
    void main(){ float g = exp(-(vUv.x*vUv.x*60. + vUv.y*vUv.y*14.)), c = exp(-(vUv.x*vUv.x*400. + vUv.y*vUv.y*60.));
      vec3 col = mix(uCW, uCT, vC);
      gl_FragColor = vec4((col*g + mix(col, vec3(1.), .6)*c) * (1. + 3.*vF*vF), 1.); }
